import js from '@eslint/js'
import tseslint from 'typescript-eslint'
import designTokens from '@qrpager/eslint-plugin-design-tokens'

/**
 * One flat config for the workspace.
 *
 * Prettier owns whitespace and ESLint owns semantics, with no overlap -- no formatting rule
 * is enabled here, which is why there is no eslint-config-prettier to switch any off.
 */
export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/.next/**',
      // Generated by `next build`, and it says so in its own header: "This file should not
      // be edited". Its triple-slash references are how Next publishes its ambient types,
      // which is exactly what @typescript-eslint/triple-slash-reference objects to -- so
      // the rule is right about the pattern and wrong about this file.
      '**/next-env.d.ts',
      '**/coverage/**',
      // ⚠ GIT-IGNORED, AND IT IS NOT SOURCE. The workspace gate's log directory, and from
      // Task 9 also the browser container's HOME -- which corepack fills with its own copy
      // of pnpm. The first lint run after that existed reported findings in
      // `storage/browsers-home/.cache/node/corepack/.../pnpm.mjs`, i.e. in a vendor's code
      // fetched by a tool. A linter that reports its own toolchain's source has no signal
      // left in it, which is the same argument `scan-css.mjs`'s `EXEMPT_SEGMENTS` makes
      // about `node_modules`.
      'storage/**',
      // ⚠ `§11`'s REVIEWER WORKTREES, AND THIS WAS A MEASURED GATE DEFECT RATHER THAN
      // TIDYING.
      //
      // `.gitignore` already excludes `/.claude/worktrees/`, which keeps them out of COMMITS
      // and does nothing about a linter: `eslint .` walks the filesystem, so two detached
      // worktrees of this repository made one run lint THREE COPIES of it. Measured on
      // 2026-11-02 while 10a's reviewers were being set up: a clean tree went from 0 findings
      // to 3,914, every one of them under a worktree path, and the real ones -- if there had
      // been any -- would have been unfindable in the noise.
      //
      // It is worse than noise. `§0.2` (b) made the two `§11` reviewers run AT THE SAME TIME
      // in their own worktrees, so from Task 10a onward the ordinary state of this repository
      // DURING a review round is that two copies of it exist inside it. A gate whose result
      // depends on whether a review happens to be in flight is not a gate.
      //
      // ⚠ AND IT IS LINE COMMENTS RATHER THAN A BLOCK, DELIBERATELY. The first version of
      // this note was a `/* … */` block that quoted the glob `.claude/worktrees/` followed by
      // a star and a slash -- which CLOSED the comment three lines early and made the whole
      // config a syntax error: `eslint .` died with `Invalid or unexpected token` and no
      // finding at all, which is a worse gate result than 3,914 of them.
      //
      // ⚠ AND IT IS `.claude/worktrees/**` RATHER THAN `.claude/**` -- `§11` QA L-2. The first
      // version excluded the whole directory, which also dropped the three files in it that
      // are TRACKED: `.claude/agents/qa-reviewer.md`, `.claude/agents/security-reviewer.md`
      // and `.claude/commands/task.md`. Those are repository content -- the `§11` briefs
      // themselves -- and a linter that silently stops covering real files is the same class
      // of defect as one that covers three copies of them, just quieter. The worktrees are
      // what has to go, and they are the only thing under this path that does.
      '.claude/worktrees/**',
      // ⚠ A SCRATCH TREE A TEST WRITES INTO, AND LEAVING IT UNIGNORED BROKE THE GATE.
      //
      // `packages/ui/test/staff-state.test.tsx` proves `§12`'s "no empty state without a next
      // action" by compiling a deliberately-wrong fixture, which means writing a real `.tsx`
      // somewhere `tsc` can resolve the package's own `node_modules` from -- so it has to be
      // inside the package. It is created and removed per run.
      //
      // Measured: `pnpm gate` died at step 1 with
      // `ENOENT ... packages/ui/test/.generated/staff-state-without-action.tsx` -- ESLint had
      // enumerated the file and it was gone before the read. A linter racing a test for a file
      // neither of them should share is a red that says nothing about the code, which is the
      // one thing a gate step must not produce.
      //
      // Ignored here, in `.prettierignore`, and in `packages/ui/tsconfig.json`'s `exclude` --
      // three lists, because this repository has three tools that walk the tree and the night
      // this was written proved that forgetting the third is the normal outcome.
      'packages/ui/test/.generated/**',
      '**/dist/**',
      'apps/api/**',
      // Generated. The gate byte-diffs each against its generator's output, so a lint fix
      // applied here would fail that diff with a change nobody authored.
      'packages/tokens/generated/**',
      'packages/contracts/src/generated/**',
      // Deliberately wrong, and read by the test that proves the rule rather than by a
      // lint pass. Linting them in the ordinary pass would make `pnpm lint` permanently red.
      'tools/design-tokens/fixtures/**',
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.strictTypeChecked,
  ...tseslint.configs.stylisticTypeChecked,

  {
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // A promise nobody awaited is the bug class that actually ships in this kind of code.
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/consistent-type-imports': 'error',
      // `any` is how a strict config stops being strict.
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unsafe-assignment': 'error',
      'no-console': ['error', { allow: ['warn', 'error'] }],
      eqeqeq: ['error', 'always'],
    },
  },

  // The §12 rule. Scoped to the surfaces §12 is binding on -- the component kit, the PWA and
  // staff app, and the public renderer -- plus the token package's own tests. It deliberately
  // does NOT apply to packages/tokens/src, which is the file that DEFINES the values: a rule
  // forbidding literals in the single source would forbid the single source.
  {
    files: ['packages/ui/**/*.{ts,tsx}', 'apps/web/**/*.{ts,tsx}', 'apps/site/**/*.{ts,tsx}'],
    plugins: { '@qrpager/design-tokens': designTokens },
    rules: {
      '@qrpager/design-tokens/no-raw-color': 'error',
      '@qrpager/design-tokens/no-raw-spacing': 'error',
      '@qrpager/design-tokens/no-raw-font-size': 'error',
    },
  },

  // Plain JavaScript: the ESLint plugin, the CSS scanner and the token generator.
  //
  // TYPE-AWARE RULES ARE OFF HERE, not suppressed per error. They are .mjs on purpose --
  // an ESLint plugin is loaded by ESLint itself, and the token generator is run by `node
  // --experimental-strip-types` -- so they belong to no tsconfig project and the type-aware
  // rules have nothing to read. Leaving them on produced a parse error per file, which is
  // the shape of a rule that is not actually running.
  {
    files: ['**/*.mjs', '**/*.js'],
    extends: [tseslint.configs.disableTypeChecked],
    languageOptions: { parserOptions: { projectService: false } },
    rules: {
      'no-console': 'off',
      'no-undef': 'off',
    },
  },

  // Config files and the generator: Node, not browser code, and not components.
  {
    files: [
      '*.config.ts',
      'playwright.config.ts',
      'vitest.config.ts',
      '**/scripts/**/*.{ts,mts}',
      'browser/**/*.ts',
    ],
    rules: {
      'no-console': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
      // A browser test reads resolved values out of an engine; the engine's own types are
      // `string` and the assertions narrow them at run time.
      '@typescript-eslint/no-non-null-assertion': 'off',
    },
  },

  // Tests assert on literal values by nature -- a contrast ratio, a hex, a pixel count. The
  // §12 rule is about COMPONENTS carrying values, and a test that may not name the value it
  // is checking cannot check it.
  {
    files: ['**/*.test.{ts,tsx}', '**/test/**/*.{ts,tsx}'],
    rules: {
      '@qrpager/design-tokens/no-raw-color': 'off',
      '@qrpager/design-tokens/no-raw-spacing': 'off',
      '@qrpager/design-tokens/no-raw-font-size': 'off',
      '@typescript-eslint/no-non-null-assertion': 'off',
    },
  },
)
